void rf_creature_33_portrait(UBYTE s,UBYTE scale,UBYTE frame) BANKED {VBK_REG=1;if(scale==2)set_bkg_data(128,16,p32+((UWORD)s*2+(frame&1))*256);else set_bkg_data(128,36,p48+((UWORD)s*2+(frame&1))*576);VBK_REG=0;memcpy(((UWORD*)BkgPalette)+20,colors+s*4,8);set_bkg_palette(5,1,colors+s*4);}
void rf_creature_33_icon(UBYTE s,UBYTE hidden,UBYTE slot) BANKED {UWORD colors4[4];UBYTE buf[64],i;memcpy(colors4,colors+s*4,8);colors4[0]=RGB(30,29,25);set_bkg_palette(slot,1,colors4);memcpy(buf,icons+(UWORD)s*64,64);if(hidden)for(i=0;i<64;i+=2)buf[i]=buf[i+1]=buf[i]|buf[i+1];VBK_REG=1;set_bkg_data(64+slot*4,4,buf);VBK_REG=0;}
